-- Generated by ekos-lakehouse (RFC 0195) from marts/rentals_by_film_rating_month.md. Approve by merging; do not edit.
{{ config(materialized='table', schema='gold', alias='rentals_by_film_rating_month') }}

select
    "film"."rating" as "rating",
    date_trunc('month', "rental"."rented_at") as "month",
    count("rental"."rental_id") as "rentals",
    count(distinct "rental"."customer_id") as "customers"
from {{ ref('public__rental') }} as "rental"
left join {{ ref('public__inventory') }} as "inventory"
    on "rental"."inventory_id" = "inventory"."inventory_id"
left join {{ ref('public__film') }} as "film"
    on "inventory"."film_id" = "film"."film_id"
group by "film"."rating", date_trunc('month', "rental"."rented_at")
